void radixSort(vector<unsigned>& a) {
    vector<unsigned> tmp(a.size());
    for (int shift = 0; shift < 32; shift += 16) {
        int cnt[65536] = {};
        for (auto x : a) cnt[(x >> shift) & 0xFFFF]++;
        partial_sum(cnt, cnt + 65536, cnt);          // positions
        for (int i = a.size() - 1; i >= 0; i--)       // backwards = STABLE
            tmp[--cnt[(a[i] >> shift) & 0xFFFF]] = a[i];
        a.swap(tmp);
    }
}

