def count_inversions_bit(a, VALS):
    vals = sorted(set(a)); rank = {v:i+1 for i,v in enumerate(vals)}
    bit = [0]*(len(vals)+1)
    def update(i):
        while i < len(bit): bit[i]+=1; i+=i&(-i)
    def query(i):
        s=0
        while i>0: s+=bit[i]; i-=i&(-i)
        return s
    inv=0
    for x in reversed(a):                     # right-to-left sweep
        r=rank[x]; inv+=query(r-1); update(r)
    return inv
